def solve(s):
    """Run-length encoding for batch 2.
    Accepts any input; if it's not a string (or bytes), returns empty list.
    Returns list of [character, count] pairs.
    """
    # Handle None or non-string inputs gracefully
    if not isinstance(s, (str, bytes)):
        return []
    if isinstance(s, bytes):
        try:
            s = s.decode()
        except Exception:
            return []
    if not s:
        return []
    res = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = ch
            count = 1
    res.append([prev, count])
    return res

