def solve(s):
    """Run‑length encoding.
    Handles:
      * str – normal string
      * bytes – decoded as UTF‑8 (ignore errors) and treated as a string
      * any iterable (list, tuple, etc.) – encodes runs of equal elements
    For other input types returns an empty list.
    """
    # Strings
    if isinstance(s, str):
        if not s:
            return []
        seq = s
    # Bytes – decode to string, ignoring errors
    elif isinstance(s, (bytes, bytearray)):
        try:
            seq = s.decode('utf-8', errors='ignore')
        except Exception:
            return []
        if not seq:
            return []
    else:
        # Try to treat as iterable
        try:
            seq = list(s)
        except Exception:
            return []
        if not seq:
            return []
    # At this point, seq is indexable sequence of elements
    res = []
    prev = seq[0]
    count = 1
    for ch in seq[1:]:
        if ch == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = ch
            count = 1
    res.append([prev, count])
    return res

